pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, uint256 withdrawAmount) public {
        vm.assume(amount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(amount >= withdrawAmount);
        address caller = address(0x1234);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = caller.balance;
        vm.prank(caller);
        c.withdrawBalance();
        uint256 contractBalanceAfter = address(c).balance;
        assertTrue(contractBalanceAfter == contractBalanceBefore - amount);
    }
}
